"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Store adalah klien Play Store sumber terbuka. Deteksi versi Play otomatis direncanakan menyusul (memerlukan autentikasi Play anonim); untuk saat ini, setiap aplikasi diarahkan ke halaman tokonya, dan Aurora Store dibuka jika sudah terinstal.",
