"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMind adalah server MCP: alat yang memberi agen AI kendali atas perangkat Android lewat ADB (aplikasi, file, log, tangkapan layar). DroidMind sendiri bukan chat.",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "DroidMind terinstal di Debian. Jalankan dengan: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Tambahkan ke agen Anda sebagai server MCP (alamatnya dicetak saat dijalankan).",
