"Every app in the F-Droid catalog, or in any of the known third-party repositories. Pick a repository, browse by category and install directly — downloads are checked against the repository's published SHA-256.": "Semua aplikasi di katalog F-Droid, atau di repositori pihak ketiga yang dikenal. Pilih repositori, jelajahi berdasarkan kategori, dan instal langsung — unduhan diperiksa terhadap SHA-256 yang dipublikasikan repositori.",
