"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "Ditemukan dengan membaca nama kelas di kode aplikasi pada ponsel ini; tidak ada yang dikirim ke mana pun. Daftar pelacak: Exodus Privacy, berlisensi ODbL 1.0. Kode yang diganti namanya oleh shrinker (R8, ProGuard) atau dimuat belakangan bisa menyembunyikan pelacak, jadi angka kecil bukan bukti bahwa tidak ada.",
