"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "Dari Manajer File: penginstalan lewat backend berhak istimewa, dengan pemeriksaan tanda tangan aplikasi ini dinonaktifkan. Android tetap memverifikasi tanda tangan sendiri: APK yang tanda tangannya tidak dapat diverifikasi akan ditandatangani dengan kunci aplikasi ini lalu diinstal, dan aplikasi yang ditandatangani pihak lain hanya bisa digantikan setelah di-uninstal (Anda akan ditanya lebih dulu).",
