"Ollama (on-device)": "Ollama (di perangkat)",
"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "Ollama belum berjalan di ponsel ini. Instal di bawah, atau masukkan alamat komputer yang menjalankannya.",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone. Ollama on a computer works too: let it listen on all addresses there, then enter the computer's address here (like 192.168.1.20:11434/v1).": "Ollama menjalankan model pemrograman langsung di ponsel ini: gratis dan offline setelah model diunduh. Dipasang di Termux; model kecil (1,5B sampai 3B) paling cocok di ponsel. Ollama di komputer juga bisa: biarkan mendengarkan di semua alamat, lalu masukkan alamat komputer di sini (seperti 192.168.1.20:11434/v1).",
"On": "Aktif",
"On device": "Di perangkat",
"On this phone": "Di ponsel ini",
"On:": "Aktif:",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "Satu perintah sekaligus per shell; output yang panjang dipangkas di layar dan pada bagian yang dikirim ke agen.",
"One file only": "Hanya satu file",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "Satu kunci untuk seluruh aplikasi. Pemindaian Pemasang dan pemindaian Morphe Helper sama-sama memakainya; keduanya tidak memintanya lagi, hanya mengarahkan ke sini saat kunci belum ada.",
"One more place to find apps": "Satu tempat lagi untuk menemukan aplikasi",
"One package per line. Duplicate entries are removed automatically.": "Satu paket per baris. Entri duplikat dihapus otomatis.",
"One source color, nine ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "Satu warna sumber, sembilan cara mengubahnya menjadi tema utuh: aksen, latar, kartu, dan teks, dalam terang dan gelap. Memilih gaya membuat tema dari warna sumber di bawah.",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "Hanya AppCleaner yang memakainya: ia membuka layar Info aplikasi sistem untuk tiap aplikasi dan mengetuk Hapus cache, untuk cache yang tidak terjangkau akses berkas apa pun. Tidak melakukan hal lain, tidak pernah membaca isi layar selain layar-layar itu, dan berhenti saat layar mati.",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "Hanya blok bertanda yang ditulis ke berkas ini; isi yang sudah ada tetap, dan menjalankan ini lagi memperbarui blok alih-alih menambah yang baru.",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "Tambahkan hanya sumber yang Anda percaya. Sumber patch menentukan apa yang masuk ke aplikasi hasil patch Anda.",
"Only apps installed on this phone": "Hanya aplikasi yang terpasang di ponsel ini",
"Only base": "Hanya base",
"Only hidden files are here. Tick Show hidden files to see them.": "Hanya ada file tersembunyi di sini. Centang Tampilkan file tersembunyi untuk melihatnya.",
"Only include common media files, documents and archives.": "Hanya sertakan berkas media umum, dokumen, dan arsip.",
"Only list what would run for each app. Nothing is run.": "Hanya tampilkan apa yang akan dijalankan untuk setiap aplikasi. Tidak ada yang dijalankan.",
"Only patches for apps installed on this phone": "Hanya patch untuk aplikasi yang terpasang di ponsel ini",
"Only text and compiled XML files can be compared line by line": "Hanya file teks dan XML terkompilasi yang bisa dibandingkan baris demi baris",
"Only the lines written by the app you pick": "Hanya baris yang ditulis oleh aplikasi yang Anda pilih",
"Only the selected apps are saved.": "Hanya aplikasi yang dipilih yang disimpan.",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "Hanya teks aplikasi ini yang berubah; nama, jalur, dan perintah dalam kotak kode tetap memakai font-nya sendiri.",
"Only this sample question is sent to them: whether the Calculator package can be disabled.": "Hanya contoh pertanyaan ini yang dikirim kepadanya: apakah paket Kalkulator boleh dinonaktifkan.",
