"The # button switches to commands.": "Tombol # beralih ke perintah.",
"The $ button switches to commands.": "Tombol $ beralih ke perintah.",
"The ADB key and the APK-signing key are created on this phone and never leave it.": "Kunci ADB dan kunci penandatanganan APK dibuat di ponsel ini dan tidak pernah meninggalkannya.",
"The APK": "APK",
"The APK is ready (saved from the browser).": "APK siap (disimpan dari browser).",
"The APK is ready.": "APK siap.",
"The Action Button": "Tombol Aksi",
"The Bluetooth link could not be set up.": "Koneksi Bluetooth tidak dapat disiapkan.",
"The Coding Agent that answers every Ask agent button: what a hidden setting, a permission, a process, a log line or an app is. Its key or sign-in is set up in the Command-Line Interface tab.": "Agen Koding yang menjawab setiap tombol Tanya agen: apa itu pengaturan tersembunyi, izin, proses, baris log, atau aplikasi. Kunci atau login-nya diatur di tab Baris Perintah.",
"The MCP button opens a sheet to give an agent extra tools (files, the web, a browser, GitHub...) through the Model Context Protocol. Pick a preset or write your own: a name, a local command or a remote address, and any key or header it needs. Pick which agents to add it to — the same server can go into two or more at once, since each agent keeps it in its own file.": "Tombol MCP membuka lembar untuk memberi agen alat tambahan (file, web, browser, GitHub...) melalui Model Context Protocol. Pilih preset atau tulis sendiri: nama, perintah lokal atau alamat jarak jauh, serta kunci atau header yang diperlukan. Pilih agen tempat menambahkannya — server yang sama dapat dimasukkan ke dua agen atau lebih sekaligus, karena setiap agen menyimpannya di file-nya sendiri.",
"The Morphe engine is not in this build of the app": "Mesin Morphe tidak ada di build aplikasi ini",
"The PDF could not be shown.": "PDF tidak dapat ditampilkan.",
"The Rish shell ended. Tap Rish mode to open a new one.": "Shell Rish berakhir. Ketuk Mode Rish untuk membuka yang baru.",
"The Rish shell is no longer running.": "Shell Rish tidak lagi berjalan.",
"The Terminal needs the app (it is not available in a plain browser)": "Terminal memerlukan aplikasinya (tidak tersedia di browser biasa)",
"The UAD-NG list has not been downloaded yet.": "Daftar UAD-NG belum diunduh.",
"The UAD-NG list has nothing on this app": "Daftar UAD-NG tidak memiliki informasi tentang aplikasi ini",
"The VirusTotal scan did not work": "Pemindaian VirusTotal tidak berhasil",
"The accessibility service is not ready": "Layanan aksesibilitas belum siap",
"The accessibility service is not ready (it is not connected), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Layanan aksesibilitas belum siap (tidak terhubung), jadi cache yang hanya bisa dihapus olehnya tetap ada. Setelah ini, gunakan “Hapus sisanya dengan aksesibilitas” di kartu AppCleaner.",
"The accessibility service is not ready (it is off), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Layanan aksesibilitas belum siap (mati), jadi cache yang hanya bisa dihapus olehnya tetap ada. Setelah ini, gunakan “Hapus sisanya dengan aksesibilitas” di kartu AppCleaner.",
"The accessibility service is not ready (no consent given), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Layanan aksesibilitas belum siap (persetujuan belum diberikan), jadi cache yang hanya bisa dihapus olehnya tetap ada. Setelah ini, gunakan “Hapus sisanya dengan aksesibilitas” di kartu AppCleaner.",
"The account has no credit left, or a spending limit was reached.": "Kredit di akun sudah habis, atau batas pengeluaran sudah tercapai.",
"The agent is still working: STOP it first": "Agen masih bekerja: ketuk STOP dulu",
"The agent pauses after this many steps.": "Agen berhenti sejenak setelah langkah sebanyak ini.",
"The app": "Aplikasi",
"The app is free, and it stays that way. If it saved you time, a coffee helps me keep improving it. Totally optional, and thank you!": "Aplikasi ini gratis, dan akan tetap begitu. Jika aplikasi ini menghemat waktu Anda, secangkir kopi membantu saya terus menyempurnakannya. Sepenuhnya opsional, dan terima kasih!",
"The app version, Android version and phone model, so a problem is easier to find.": "Versi aplikasi, versi Android, dan model ponsel, agar masalah lebih mudah ditemukan.",
"The apps you patch are listed here, with the log of each run, so you can install them again, share them or save them to Downloads.": "Aplikasi yang Anda patch tercantum di sini, beserta log tiap proses, sehingga Anda dapat memasangnya lagi, membagikannya, atau menyimpannya ke Unduhan.",
"The archive file is rewritten without this file.": "File arsip ditulis ulang tanpa file ini.",
"The archive file is rewritten without this folder and everything in it.": "File arsip ditulis ulang tanpa folder ini dan seluruh isinya.",
"The archive is deleted only when every file of it was extracted, with nothing skipped.": "Arsip dihapus hanya jika semua filenya berhasil diekstrak, tanpa ada yang dilewati.",
