"The exclusions SD Maid SE ships with come back, the ones you removed too. Yours stay.": "Pengecualian bawaan SD Maid SE kembali, termasuk yang pernah Anda hapus. Milik Anda tetap ada.",
"The exclusions could not be read.": "Pengecualian tidak dapat dibaca.",
"The extra button on every row of the Apps list. Choose what a tap on it does. Press and hold it on a row for a sheet with every action for that app.": "Tombol tambahan di setiap baris daftar Aplikasi. Pilih apa yang terjadi saat diketuk. Tekan lama pada baris untuk lembar berisi semua aksi untuk aplikasi itu.",
"The extra keys work like Termux's: ESC clears the line, TAB completes a file name, CTRL-C stops what is running, the arrows go through earlier commands and move the cursor, HOME and END jump in the line, and | / - ~ are there because phone keyboards hide them.": "Tombol tambahan bekerja seperti di Termux: ESC menghapus baris, TAB melengkapi nama file, CTRL-C menghentikan proses yang berjalan, tanda panah menelusuri perintah sebelumnya dan menggerakkan kursor, HOME dan END melompat di dalam baris, dan | / - ~ disediakan karena keyboard ponsel menyembunyikannya.",
"The extraction could not start": "Ekstraksi tidak dapat dimulai",
"The file": "File",
"The file and its log are removed. The app on the phone is not touched.": "Berkas dan lognya dihapus. Aplikasi di ponsel tidak disentuh.",
"The file chooser needs the app build": "Pemilih file memerlukan versi resmi aplikasi",
"The file is removed from this phone's storage, not just from the list. An Undo bar stays for a few seconds, and the file only goes for good once that bar is gone.": "File dihapus dari penyimpanan ponsel ini, bukan hanya dari daftar. Bilah Urungkan tetap muncul beberapa detik, dan file baru benar-benar hilang setelah bilah itu menghilang.",
"The file was saved, but it is not an app file (unknown). Choose another download in the browser.": "Berkas tersimpan, tetapi bukan berkas aplikasi (tidak diketahui). Pilih unduhan lain di browser.",
"The fingerprint is shown in the app build": "Fingerprint ditampilkan di build aplikasi",
