"The manifest does not ask for any extra library (no uses-library entry).": "Manifest tidak meminta pustaka tambahan apa pun (tanpa entri uses-library).",
"The name in code type is the key. It is the same on every phone that has the setting.": "Nama pada jenis kode adalah kuncinya. Sama di setiap ponsel yang memiliki pengaturan itu.",
"The older storage permission some apps still check for.": "Izin penyimpanan lama yang masih diperiksa sebagian aplikasi.",
"The pairing code has 6 digits": "Kode pairing terdiri dari 6 digit",
"The password is used only for this archive, only while it is open. It is never saved.": "Kata sandi ini hanya digunakan untuk arsip ini, dan hanya saat arsip ini terbuka. Kata sandi tidak pernah disimpan.",
"The patch bundle may be damaged or made for a newer Morphe. Update the source in Sources.": "Paket patch mungkin rusak atau dibuat untuk Morphe yang lebih baru. Perbarui sumber di Sumber.",
"The patched APK is only saved. Install it from Patched APKs.": "APK hasil patch hanya disimpan. Pasang dari APK hasil patch.",
"The patched APK was deleted after the install.": "APK hasil patch dihapus setelah dipasang.",
"The patcher could not be started": "Patcher tidak dapat dimulai",
"The patcher ran out of memory. Close other apps and try again, or turn on \"Strip unused native libraries\" in the patcher settings.": "Patcher kehabisan memori. Tutup aplikasi lain dan coba lagi, atau aktifkan “Buang pustaka native yang tidak dipakai” di pengaturan patcher.",
"The patcher stopped": "Patcher berhenti",
"The patcher stops and nothing is saved.": "Patcher berhenti dan tidak ada yang disimpan.",
"The patches could not be read": "Patch tidak dapat dibaca",
"The patches do not support this version of the app. Get a supported version with Morphe Helper, or turn on \"Patch unsupported versions\" in the patcher settings.": "Patch tidak mendukung versi aplikasi ini. Dapatkan versi yang didukung dengan Morphe Helper, atau aktifkan “Patch versi yang tidak didukung” di pengaturan patcher.",
"The paths could not be read.": "Jalur tidak dapat dibaca.",
"The phone may still apply it. It is looked at again in a moment.": "Ponsel mungkin tetap menerapkannya. Akan diperiksa lagi sebentar lagi.",
"The phone may still apply it. The list is read again in a moment.": "Ponsel mungkin tetap menerapkannya. Daftar akan dibaca lagi sebentar lagi.",
"The phone's browser": "Browser ponsel",
"The project gives no description for this package.": "Proyek tidak menyediakan deskripsi untuk paket ini.",
"The providers do not support Android officially: the tool may not run on every phone. The Terminal shows its exact messages when something fails.": "Penyedia tidak mendukung Android secara resmi: alat ini mungkin tidak berjalan di semua ponsel. Terminal menampilkan pesan persisnya jika ada yang gagal.",
"The pull did not finish": "Penarikan tidak selesai",
"The push did not finish": "Pengiriman tidak selesai",
"The quick brown fox jumps over the lazy dog.": "The quick brown fox jumps over the lazy dog.",
"The repository must be an https:// address": "Repositori harus berupa alamat https://",
"The request could not be sent": "Permintaan tidak dapat dikirim",
"The request could not start": "Permintaan tidak dapat dimulai",
"The resolution the device draws at, width x height in pixels.": "Resolusi yang digunakan perangkat untuk menggambar, lebar x tinggi dalam piksel.",
"The round checkmark button (when apps are selected)": "Tombol centang bulat (saat aplikasi dipilih)",
"The scan failed: unknown error": "Pemindaian gagal: error tidak diketahui",
"The screen shows the settings of one app after the other for a moment while Clear cache is tapped for each app that still has a cache the files cannot reach. A cover shows what is happening, with a Cancel button. It stops if the screen turns off.": "Layar menampilkan sebentar pengaturan aplikasi satu per satu saat Hapus cache diketuk untuk tiap aplikasi yang masih punya cache yang tidak terjangkau berkas. Penutup menunjukkan apa yang terjadi, dengan tombol Batal. Berhenti jika layar mati.",
