"The search failed": "Pencarian gagal",
"The search failed.": "Pencarian gagal.",
"The search failed: unknown error": "Pencarian gagal: kesalahan tidak dikenal",
"The search took too long. Tap Find APKs to try again.": "Pencarian terlalu lama. Ketuk Cari APK untuk mencoba lagi.",
"The service is off.": "Layanan mati.",
"The service is switched on but has not connected yet; turn it off and on again in the accessibility settings.": "Layanan sudah dinyalakan tetapi belum terhubung; matikan lalu nyalakan lagi di pengaturan aksesibilitas.",
"The setting's name, table and current value are sent to them.": "Nama, tabel, dan nilai saat ini dari pengaturan itu dikirim kepada mereka.",
"The shell did not start": "Shell gagal dimulai",
"The small messages while a change is made and checked": "Pesan-pesan kecil saat perubahan dibuat dan diperiksa",
"The source could not be added": "Sumber tidak dapat ditambahkan",
"The sources that are on do not have patches yet, or the patch engine could not read them. Open Sources to update them.": "Sumber yang aktif belum punya patch, atau mesin patch tidak dapat membacanya. Buka Sumber untuk memperbaruinya.",
"The sources, Fast mode and VirusTotal flow of Morphe Helper follow": "Sumber, Mode cepat, dan alur VirusTotal Morphe Helper mengikuti",
"The store needs the app build (Android bridge).": "Toko memerlukan build aplikasi (bridge Android).",
"The system colors are not available on this phone.": "Warna sistem tidak tersedia di ponsel ini.",
"The system colors could not be read here.": "Warna sistem tidak dapat dibaca di sini.",
"The system font is back.": "Font sistem kembali digunakan.",
"The terminal could not be loaded. Close it and try again.": "Terminal tidak dapat dimuat. Tutup dan coba lagi.",
"The terminal did not start": "Terminal tidak dimulai",
"The test could not start": "Pengujian tidak dapat dimulai",
"The text above is sent to them.": "Teks di atas dikirim kepada mereka.",
"The text is identical (only the packing differs).": "Teksnya identik (hanya pengemasannya yang berbeda).",
"The text of this app. Names of apps, files and commands are not translated.": "Teks aplikasi ini. Nama aplikasi, file, dan perintah tidak diterjemahkan.",
"The theme was not changed": "Tema tidak diubah",
"The three shells": "Tiga shell",
"The three tables": "Tiga tabel",
"The token works. The Copilot CLI uses it from now on.": "Token berfungsi. Copilot CLI akan memakainya mulai sekarang.",
"The two archives hold identical files.": "Kedua arsip berisi file yang identik.",
