"Then allow this app to \"Run commands in Termux environment\" and test the connection. Termux setup in the Terminal settings walks you through it.": "Lalu izinkan aplikasi ini untuk “Run commands in Termux environment” dan uji koneksinya. Penyiapan Termux di pengaturan Terminal akan memandu Anda.",
"There are no saved lists to back up yet": "Belum ada daftar tersimpan untuk dicadangkan",
"There are no saved lists to back up yet; Restore works anyway.": "Belum ada daftar tersimpan untuk dicadangkan; Pulihkan tetap berfungsi.",
"There are no saved lists to share yet": "Belum ada daftar tersimpan untuk dibagikan",
"There are no usable lists in that file.": "Tidak ada daftar yang dapat dipakai di berkas itu.",
"There is no key yet": "Belum ada kunci",
"There is no undo.": "Tidak dapat diurungkan.",
"There is nothing to delete. Scan first.": "Tidak ada yang perlu dihapus. Pindai dulu.",
"These apps are currently selected for this action:": "Aplikasi ini sedang dipilih untuk tindakan ini:",
"These apps are uninstalled but their data folders are still on the phone. The data of the apps you tick is deleted for good.": "Aplikasi ini sudah dihapus instalannya tetapi folder datanya masih ada di ponsel. Data aplikasi yang Anda centang dihapus selamanya.",
"These apps are uninstalled. Without Root the app cannot see which of them still have data, so clearing all of them is safe but may find nothing for some. The data of the apps you tick is deleted for good.": "Aplikasi ini sudah dihapus instalannya. Tanpa Root aplikasi tidak bisa melihat mana yang masih memiliki data, jadi menghapus semuanya aman tetapi mungkin tidak menemukan apa pun untuk sebagian. Data aplikasi yang Anda centang dihapus selamanya.",
"These apps' releases live on sites this app can't check directly. Obtainium can track them.": "Rilis aplikasi ini berada di situs yang tidak dapat diperiksa langsung oleh aplikasi ini. Obtainium dapat melacaknya.",
"These files are too different to compare line by line. View each one instead.": "File-file ini terlalu berbeda untuk dibandingkan baris demi baris. Lihat masing-masing saja.",
"They go on when the browser is closed. Pause keeps what was downloaded and Resume asks the site for the rest only (a site that cannot do that starts the file again).": "Unduhan berlanjut saat browser ditutup. Jeda menyimpan yang sudah terunduh dan Lanjutkan hanya meminta sisanya dari situs (situs yang tidak bisa itu akan mengulang berkas dari awal).",
"They will be skipped unless you patch anyway, which may fail or break the app.": "Akan dilewati kecuali Anda tetap mem-patch, yang bisa gagal atau merusak aplikasi.",
"Third-party packages only": "Hanya paket pihak ketiga",
"This App's ADB Key": "Kunci ADB Aplikasi Ini",
"This Shizuku version is too old. Please update Shizuku.": "Versi Shizuku ini terlalu lama. Perbarui Shizuku.",
"This action cannot be undone.": "Tindakan ini tidak dapat diurungkan.",
"This action needs access to files on this phone.": "Tindakan ini memerlukan akses ke file di ponsel ini.",
