"This agent has no sign-in tool": "Agen ini tidak memiliki alat login",
"This app": "Aplikasi ini",
"This app (sandbox)": "Aplikasi ini (sandbox)",
"This app cannot read storage. Grant All-files access, or choose a font file by hand (that needs no access).": "Aplikasi ini tidak dapat membaca penyimpanan. Berikan akses ke semua file, atau pilih file font secara manual (tidak perlu akses).",
"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "Aplikasi ini tidak meminta layar sentuh, keyboard, atau navigasi tertentu (tanpa entri uses-configuration), sehingga berjalan dengan apa pun yang dimiliki ponsel ini.",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "Aplikasi ini tidak mencantumkan fitur perangkat keras atau perangkat lunak yang dibutuhkan (tanpa entri uses-feature).",
"This app has no activities.": "Aplikasi ini tidak memiliki activity.",
"This app may not run commands in Termux yet.": "Aplikasi ini mungkin belum dapat menjalankan perintah di Termux.",
"This app now has its own private ADB key. Tap the mode badge for details.": "Aplikasi ini kini memiliki kunci ADB pribadi sendiri. Ketuk lencana mode untuk detailnya.",
"This app's code could not be read (it has none, or the file is not readable), so nothing can be said about trackers.": "Kode aplikasi ini tidak dapat dibaca (tidak ada, atau berkasnya tidak terbaca), jadi tidak ada yang bisa dikatakan tentang pelacak.",
"This app's own shell - no root, ADB or package manager.": "Shell milik aplikasi ini - tanpa root, ADB, atau manajer paket.",
"This app's own user and group id": "ID pengguna dan grup milik aplikasi ini",
"This app’s key · 2048-bit RSA · in secure hardware": "Kunci aplikasi ini · RSA 2048-bit · di perangkat keras aman",
"This app’s key · 2048-bit RSA · in the Android Keystore": "Kunci aplikasi ini · RSA 2048-bit · di Android Keystore",
"This archive is view-only": "Arsip ini hanya dapat dilihat",
"This build": "Build ini",
"This build of the app does not contain the Morphe engine, so patching is not available. Sources, the community finder and downloads still work. Install a release build of the app to patch.": "Build aplikasi ini tidak berisi mesin Morphe, jadi patching tidak tersedia. Sumber, pencari komunitas, dan unduhan tetap berfungsi. Pasang build rilis aplikasi untuk mem-patch.",
"This build of the app does not contain the Morphe engine. Install a release build.": "Build aplikasi ini tidak berisi mesin Morphe. Pasang build rilis.",
"This can cut the ADB connection this app uses, so you may not be able to change it back from here.": "Ini dapat memutus koneksi ADB yang digunakan aplikasi ini, sehingga Anda mungkin tidak bisa mengubahnya kembali dari sini.",
"This can lock you out of parts of the phone (the screen, the keyboard or accessibility).": "Ini dapat membuat Anda terkunci dari bagian ponsel (layar, keyboard, atau aksesibilitas).",
"This cannot be undone.": "Ini tidak dapat dibatalkan.",
"This device has not allowed this phone yet. Look at its screen and tap": "Perangkat ini belum mengizinkan ponsel ini. Lihat layarnya dan ketuk",
"This file could not be read": "File ini tidak dapat dibaca",
"This file was changed by something else since you opened it. Save your version over it?": "File ini diubah oleh pihak lain sejak Anda membukanya. Simpan versi Anda di atasnya?",
"This folder": "Folder ini",
"This folder is empty.": "Folder ini kosong.",
"This font could not be read (it may be over 6 MB, or out of reach)": "Font ini tidak dapat dibaca (mungkin lebih dari 6 MB, atau tidak terjangkau)",
"This font could not be shown.": "Font ini tidak dapat ditampilkan.",
"This is already what the phone uses.": "Ini sudah yang digunakan ponsel.",
