"This is the top of this storage": "Ini adalah bagian teratas penyimpanan ini",
"This look is an old custom palette: choose a palette or a palette style first": "Tampilan ini adalah palet kustom lama: pilih palet atau gaya palet terlebih dahulu",
"This looks like a binary file. Pull it to this phone instead.": "File ini tampaknya file biner. Tarik ke ponsel ini saja.",
"This needs the app build.": "Ini memerlukan build aplikasi.",
"This only works with the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); an agent used only with an API key cannot use one here.": "Ini hanya berfungsi dengan agen yang login lewat alat command-line mereka sendiri di Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); agen yang hanya memakai kunci API tidak dapat menggunakannya di sini.",
"This package carries data files that live outside the APK. Right after the install succeeds they are copied into place.": "Paket ini membawa file data yang berada di luar APK. Segera setelah penginstalan berhasil, file tersebut disalin ke tempatnya.",
"This page is running without the app, so there is no phone to read the settings from.": "Halaman ini berjalan tanpa aplikasi, jadi tidak ada ponsel untuk membaca pengaturan.",
