"This phone is not connected to its own ADB. Turn on ADB in this app's Working mode first (Working Mode button at the top), then try again.": "Ponsel ini tidak terhubung ke ADB-nya sendiri. Aktifkan ADB di Mode kerja aplikasi ini terlebih dahulu (tombol Mode Kerja di bagian atas), lalu coba lagi.",
