"This store needs the app build (Android bridge).": "Toko ini memerlukan build aplikasi (bridge Android).",
"This version is not one the patches list. Patching may fail. Get a supported version with Morphe Helper, or patch anyway.": "Versi ini bukan salah satu yang tercantum di patch. Patching mungkin gagal. Dapatkan versi yang didukung dengan Morphe Helper, atau tetap patch.",
