"Type a command for the device and press Run. A line that starts with \"adb \" goes to adb itself (adb pull, adb forward ...).": "Ketik perintah untuk perangkat lalu tekan Jalankan. Baris yang diawali “adb ” dikirim ke adb itu sendiri (adb pull, adb forward ...).",
"Type a command for the device and press Run. Start a line with \"adb \" to send it to adb itself (adb pull, adb forward ...). The $ button switches to adb for every line.": "Ketik perintah untuk perangkat lalu tekan Jalankan. Awali baris dengan “adb ” untuk mengirimnya ke adb itu sendiri (adb pull, adb forward ...). Tombol $ beralih ke adb untuk setiap baris.",
"Type a whole number, like 280": "Ketik bilangan bulat, seperti 280",
"Type in the search box to find a word anywhere in the guide. This guide is in English.": "Ketik di kotak pencarian untuk menemukan kata di mana saja dalam panduan. Panduan ini dalam bahasa Inggris.",
"Type it like 450x450": "Ketik seperti 450x450",
"Type something to search for.": "Ketik sesuatu untuk dicari.",
