"v1 is the old signature kept in the META-INF folder. v2, v3 and v3.1 sit in the APK signing block; v3 and v3.1 allow the signing key to be changed later. The base APK is the one read.": "v1 adalah tanda tangan lama yang disimpan di folder META-INF. v2, v3, dan v3.1 berada di blok penandatanganan APK; v3 dan v3.1 memungkinkan kunci penandatanganan diganti di kemudian hari. Yang dibaca adalah APK base.",
